/**
 * The India Post pincodes inside a city / district, for the "Pincodes" picker on the booking-rules page.
 * Data: ./pincodes/<GST state code>.json, generated by tools/build-pincodes.py from the India Post pincode directory.
 * One file per state, loaded only when a state is chosen. Every pincode belongs to exactly one district.
 */
export interface PincodeEntry { pin: string; name: string }
export interface PincodeList {
  pins: PincodeEntry[];
  /** Set when the city is a town inside a district (Hosur → Krishnagiri): the list is only the post offices named after the town. */
  parent?: string;
}
type StateFile = { cities: Record<string, [string, string][]>; towns: Record<string, string> };

const files = import.meta.glob<StateFile>("./pincodes/*.json", { import: "default" });
const cache = new Map<string, Promise<StateFile | null>>();
const key = (v: string) => v.trim().toLowerCase();

function load(state: string): Promise<StateFile | null> {
  let hit = cache.get(state);
  if (!hit) {
    const loader = files[`./pincodes/${state}.json`];
    hit = loader ? loader().catch(() => null) : Promise.resolve(null);
    cache.set(state, hit);
  }
  return hit;
}

/** The pincodes of a city / district of one state (its GST code); null when no list exists for it. */
export async function pincodesOf(state: string, city: string): Promise<PincodeList | null> {
  const file = await load(state);
  if (!file) return null;
  const name = Object.keys(file.cities).find((c) => key(c) === key(city));
  if (!name) return null;
  const parent = file.towns[name];
  return { pins: file.cities[name]!.map(([pin, label]) => ({ pin, name: label })), ...(parent ? { parent } : {}) };
}

/** A saved place's area is a pincode (six digits) rather than an area name. */
export const isPincode = (area?: string) => /^[1-9]\d{5}$/.test((area ?? "").trim());
